<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #172033; background: #f5f7fb; }
    body { margin: 0; }
    main { max-width: 760px; margin: 0 auto; padding: 48px 24px; }
    h1 { margin: 0 0 28px; font-size: 2rem; }
    form { display: flex; gap: 10px; margin-bottom: 24px; }
    label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0, 0, 0, 0); }
    input { flex: 1; min-width: 0; padding: 11px 12px; border: 1px solid #bdc7d8; border-radius: 6px; font: inherit; }
    button { border: 0; border-radius: 6px; padding: 11px 16px; background: #2459c4; color: white; font: inherit; cursor: pointer; }
    button:hover { background: #19469f; }
    .project-list { display: grid; gap: 10px; }
    [data-testid="project-row"] { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 16px; background: white; border: 1px solid #e0e5ee; border-radius: 8px; }
    [role="alert"] { color: #b42318; margin: -10px 0 18px; }
    .back { margin-bottom: 24px; }
    @media (max-width: 480px) { form { flex-direction: column; } }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const escapeHtml = (value) => String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);

    async function showList() {
      const projects = await fetch('/api/projects').then(response => response.json());
      app.innerHTML = `<h1>Workboard</h1>
        <form id="create-form"><label for="project-name">Project name</label><input id="project-name" name="name" type="text" aria-label="Project name"><button type="submit">Create project</button></form>
        <div id="alert" role="alert" hidden></div>
        <section class="project-list" aria-label="Projects">${projects.map(project => `<div data-testid="project-row"><span>${escapeHtml(project.name)}</span><button type="button" data-open="${project.id}">Open project</button></div>`).join('')}</section>`;
      app.querySelector('#create-form').addEventListener('submit', async event => {
        event.preventDefault();
        const name = app.querySelector('#project-name').value.trim();
        if (!name) {
          const alert = app.querySelector('#alert');
          alert.textContent = 'Project name is required';
          alert.hidden = false;
          return;
        }
        const response = await fetch('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
        if (response.ok) showList();
      });
      app.querySelectorAll('[data-open]').forEach(button => button.addEventListener('click', () => {
        history.pushState({}, '', `/projects/${button.dataset.open}`);
        showRoute();
      }));
    }

    async function showProject(id) {
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) { history.replaceState({}, '', '/'); return showList(); }
      const project = await response.json();
      app.innerHTML = `<button class="back" type="button">Projects</button><h1>${escapeHtml(project.name)}</h1>`;
      app.querySelector('.back').addEventListener('click', () => {
        history.pushState({}, '', '/');
        showRoute();
      });
    }

    function showRoute() {
      const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
      if (match) showProject(match[1]);
      else showList();
    }
    window.addEventListener('popstate', showRoute);
    showRoute();
  </script>
</body>
</html>
